# Source for q/ae-instr-contrast3.js: Echo instrumentation + Contrast third batch.
EI="Echo instrumentation"; CT="Contrast"
Q=[
# --- Transducers and basic settings ---
(EI,"Adult transthoracic echo usually uses a phased array transducer because it:","Has a small footprint that fits between ribs and steers the beam electronically",["Has no crystals","Produces only linear images","Works only at 15 MHz"],"The sector image fans out from a small contact point.","F"),
(EI,"A typical transducer frequency for an adult transthoracic echo is about:","1.5 to 3.5 MHz (often around 2 to 2.5 MHz fundamental)",["10 to 15 MHz","20 to 40 MHz","0.1 to 0.5 MHz"],"Higher frequencies (5 to 8 MHz) are used for children and thin adults.","F"),
(EI,"Which control adjusts brightness at specific depths?","Time gain compensation (TGC)",["Overall gain only","Sector width","Baseline"],"Lateral gain (LGC) adjusts brightness across the image.","F"),
(EI,"Persistence (frame averaging) set too high causes:","Blurring of fast-moving structures such as valves",["Sharper valve motion","Higher frame rate","Better Doppler"],"Use low persistence for cardiac imaging.","F"),
(EI,"Lowering the dynamic range (compression) makes the image:","More contrasty, with fewer gray shades",["Smoother with more gray shades","Larger","Deeper"],"A wide dynamic range shows subtle differences in tissue brightness.","F"),
(EI,"Where should the transmit focus be placed?","At or just below the structure of interest",["At the top of the screen always","Far below the heart","Anywhere; it has no effect"],"Focus improves lateral resolution at that depth.","F"),
(EI,"Raising line density (more scan lines per frame) will:","Improve lateral detail but lower frame rate",["Raise frame rate","Remove all artifacts","Improve penetration"],"There is always a trade-off between image detail and speed.","F"),
(EI,"Multi-line acquisition (parallel receive processing) improves:","Frame rate, by forming several receive lines for each transmit pulse",["Penetration","Axial resolution only","Doppler accuracy"],"It is important for 3D and high frame-rate imaging.","C"),
(EI,"For wall motion assessment, the frame rate should usually be at least about:","30 frames per second",["5 frames per second","1 frame per second","500 frames per second"],"Higher frame rates capture brief changes in contraction.","F"),
(EI,"In tissue Doppler, the usual high-pass wall filter is changed so that:","Low-velocity, high-amplitude signals from the myocardium are kept and blood flow is removed",["Blood flow is enhanced","All signals are removed","Only noise is shown"],"Tissue moves slowly but reflects strongly.","C"),
(EI,"Color 'write priority' (color threshold) decides:","Whether a pixel shows grayscale or color when both are present",["The color map","The baseline position","The PRF"],"A high setting favors color over grayscale.","C"),
(EI,"Color 'invert' changes:","Which direction is shown in red or blue, not the actual flow direction",["The flow direction","The velocity","The frame rate"],"Check the color bar before describing flow direction.","F"),
(EI,"An 'anatomical' (steerable) M-mode lets the sonographer:","Place the M-mode line in any direction on a stored 2D loop",["Measure velocity","Use only CW","Image in 3D"],"It helps when the cursor cannot be placed perpendicular in the live image.","C"),
(EI,"Color M-mode is useful because it has:","Very high temporal resolution, showing timing of flow events",["Better spatial detail than 2D","No aliasing","3D information"],"It is used for flow propagation and timing AR or LVOT flow.","F"),
# --- 3D and advanced ---
(EI,"Live (real-time) 3D imaging differs from full-volume 3D because live 3D:","Shows a narrow volume in real time, while full volume combines several beats for a wider view",["Uses several beats","Has no frame rate","Needs no transducer"],"Full volume has higher frame rate and size but can have stitching artifacts.","C"),
(EI,"Multiplanar reconstruction (MPR) of a 3D data set allows:","Cutting the volume in any plane to get true short- or long-axis views",["Measuring Doppler velocity","Removing all artifacts","Raising frame rate"],"It helps measure valve areas and annular dimensions accurately.","F"),
(EI,"Biplane (simultaneous two-plane) imaging with a matrix probe shows:","Two 2D planes at once, usually at 90° to each other",["Only M-mode","Only Doppler","3D color only"],"It helps during procedures and to avoid foreshortening.","F"),
(EI,"A matrix-array transducer contains:","Thousands of elements arranged in a grid for 3D imaging",["A single crystal","One row of elements only","No elements"],"The grid allows steering in two directions.","F"),
(EI,"Strain values may differ between ultrasound machines because:","Vendors use different tracking software and definitions",["Strain is always identical","Strain depends only on heart rate","Different gels are used"],"Follow-up studies should use the same vendor when possible.","F"),
(EI,"Echo images are stored and shared using the standard format called:","DICOM",["JPEG only","PDF","MP3"],"DICOM files are stored on a PACS (picture archiving system).","F"),
(EI,"Intracardiac echo (ICE) uses:","A small transducer on a catheter placed in the heart, often during ablation",["A transducer on the chest","A TEE probe","A 3D surface probe"],"It avoids general anesthesia that TEE might require.","F"),
(EI,"Most TEE probes stop scanning automatically when the tip temperature reaches about:","42 to 43 °C",["20 °C","37 °C","60 °C"],"This protects the esophagus from heat injury.","C"),
(EI,"A TEE probe should be checked for electrical leakage and damage:","Regularly and after any visible damage to the shaft",["Never","Only once in its life","Only when it stops working"],"Bite marks or cracks can expose patients to current or infection.","F"),
(EI,"A bite guard is used during TEE to:","Protect the probe and the patient's teeth",["Improve the image","Measure blood pressure","Hold the tongue"],"Damaged shafts can be electrically unsafe.","F"),
# --- Artifacts ---
(EI,"A bright line or 'flap' in the ascending aorta that is exactly twice the distance of the posterior aortic wall from the transducer is most likely:","A reverberation artifact",["A dissection flap","Thrombus","A normal valve"],"Real flaps move independently and do not follow simple distance rules.","C"),
(EI,"Haze at the LV apex that does not move and looks like thrombus may be:","Near-field clutter (reverberation)",["True thrombus always","A tumor","A papillary muscle"],"Try a higher frequency, change position or use contrast.","F"),
(EI,"Acoustic shadowing behind a mechanical mitral valve on TTE prevents seeing:","The LA and MR jets",["The LV apex","The aortic arch","The IVC"],"TEE images the LA from behind, avoiding the shadow.","F"),
(EI,"A side-lobe artifact in the aorta may look like:","A linear echo within the lumen that does not move with the aortic walls",["A real tear","A clot","Normal blood"],"Change view and lower gain to check.","C"),
(EI,"A 'mirror image' of the heart or a second copy of a structure on the far side of a strong reflector is caused by:","Mirror artifact",["Aliasing","Refraction","Side lobes"],"The machine assumes sound always travels in a straight line.","F"),
(EI,"An object seen twice side by side on PSAX, especially near the aortic valve, may be from:","Refraction (lens) artifact",["Mirror artifact","Shadowing","Enhancement"],"Change the window or angle to confirm.","C"),
(EI,"Color Doppler 'blooming' happens when:","Color gain is too high, so color spills beyond vessel or jet edges",["Gain is too low","The PRF is too high","Harmonics are used"],"Lower the color gain until noise just disappears.","F"),
# --- Doppler setup ---
(EI,"When using high-PRF Doppler, the sonographer must be careful because:","More than one sample gate is active, so the signal source may be uncertain",["Aliasing is worse","The scale is lower","There is no gate at all"],"It allows higher velocities than standard PW at a given depth.","F"),
(EI,"A dedicated non-imaging (pencil) CW probe is better than an imaging probe for AS because it:","Is smaller, more sensitive and fits in more windows",["Shows a 2D image","Has a lower frequency only","Measures PW Doppler"],"It is often used from right parasternal and suprasternal windows.","F"),
(EI,"The spectral Doppler 'scale' should be set so that the signal:","Fills about two-thirds to three-quarters of the display without aliasing",["Is very small near the baseline","Wraps around the baseline","Is off the screen"],"A larger display improves measurement accuracy.","F"),
(EI,"Sample volume (gate) size for LVOT PW Doppler is usually about:","3 to 5 mm",["10 to 20 mm","0.1 mm","50 mm"],"A gate that is too large adds spectral broadening.","F"),
# --- Contrast agents ---
(CT,"Which ultrasound enhancing agent has a lipid shell with perflutren gas?","Definity (perflutren lipid microspheres)",["Optison","Lumason","Agitated saline"],"Optison has an albumin shell; Lumason contains sulfur hexafluoride gas in a lipid shell.","C"),
(CT,"Optison microbubbles have a shell made of:","Human albumin",["Lipid","Sugar","Plastic"],"Patients allergic to blood products or albumin should not receive it.","C"),
(CT,"Lumason (SonoVue) contains which gas?","Sulfur hexafluoride",["Perflutren","Oxygen","Room air"],"It is approved for adults and children in some indications.","C"),
(CT,"UEAs use heavy, poorly soluble gases (such as perfluorocarbons) because:","The bubbles last longer in the blood and pass through the lungs",["They dissolve instantly","They are cheaper than air","They are radioactive"],"Air bubbles dissolve quickly and are filtered by the lungs.","F"),
(CT,"For LV opacification, the mechanical index is typically set at about:","0.1 to 0.3 (low MI)",["1.5 to 1.9","Exactly 1.0","3.0"],"Low MI keeps bubbles intact and allows harmonic resonance.","F"),
(CT,"Too much contrast in the LV causes:","Shadowing of the far field, hiding the basal segments and mitral valve",["Better basal views","Swirling","No effect"],"Wait for the dose to clear or lower the infusion.","F"),
(CT,"UEAs are usually given with:","A slow IV injection followed by a slow saline flush, or a continuous infusion",["Fast large bolus with a rapid flush","An injection into an artery","An oral dose"],"Follow the product label for dose and rate.","F"),
(CT,"During contrast echo, the lab must have available:","Resuscitation equipment and trained staff",["Only a blood pressure cuff","Nothing special","A CT scanner"],"Serious reactions are rare but can occur within minutes.","F"),
(CT,"The current main contraindication listed for UEAs is:","Known hypersensitivity to the agent or its components",["Any heart failure","Any pregnancy","Pulmonary hypertension"],"Right-to-left shunt is no longer a labeled contraindication for some agents.","C"),
(CT,"Contrast improves EF measurement by:","Showing the endocardial border clearly, giving more accurate and repeatable volumes",["Raising the EF","Removing the need for tracing","Measuring strain"],"Contrast volumes are closer to MRI values.","F"),
(CT,"Contrast use during Doppler can cause:","Overestimation of velocities because of brighter signals and blooming",["Lower velocities always","No effect","Disappearance of the signal"],"Lower the Doppler gain when contrast is present.","C"),
(CT,"Apical hypertrophic cardiomyopathy on contrast echo shows:","An 'ace of spades' shaped LV cavity in diastole",["A dilated apex","An apical aneurysm only","Normal shape"],"Thick apical walls narrow the apex.","F"),
(CT,"Contrast helps in suspected LV apical aneurysm with mid-cavity HCM by showing:","The thin-walled aneurysm and any thrombus inside it",["The aortic valve","Coronary arteries","Pericardial fluid only"],"Apical aneurysm raises sudden death and stroke risk.","C"),
(CT,"Contrast can help tell a pseudo-thrombus (near-field artifact) from a true apical thrombus because:","Contrast fills the apex fully when there is no thrombus",["Thrombus enhances brightly","Artifact disappears without contrast","It makes no difference"],"A real thrombus remains as a dark filling defect.","F"),
(CT,"A vascular tumor on contrast echo usually shows:","Enhancement (bright filling) because it has a blood supply",["No enhancement","Shadowing only","A dark void"],"Thrombus does not enhance because it has no blood supply.","F"),
(CT,"Destruction-replenishment imaging measures perfusion by:","Destroying bubbles with high-MI flash frames and watching how fast they refill the myocardium",["Measuring LVOT VTI","Measuring IVC size","Counting heart rate"],"Slow refill suggests reduced blood flow.","C"),
(CT,"In real-time myocardial contrast echo, a perfusion defect in a segment with normal wall motion may show:","Early ischemia before wall motion changes",["Normal finding always","Scar only","Pericardial disease"],"Perfusion abnormalities appear early in the ischemic cascade.","C"),
(CT,"Contrast is often helpful for which patients in the ICU?","Patients with poor windows, such as those on ventilators or after surgery",["Only patients with excellent windows","Only children","Only outpatients"],"It often makes a non-diagnostic study diagnostic.","F"),
(CT,"Microbubbles in UEAs are about the size of:","Red blood cells, small enough to pass through capillaries",["Large air pockets","Grains of sand","Platelets only"],"Most are about 1 to 10 µm.","F"),
(CT,"Contrast use should be documented with:","The agent, dose, route, time and any reaction",["Nothing","Only the patient's name","Only the machine settings"],"Documentation is part of safe practice and billing.","F"),
(CT,"A sudden drop in blood pressure, back pain and flushing soon after a UEA suggests:","A possible reaction; stop the infusion and call for help",["A normal response","Better image quality","No action needed"],"Back pain and flushing can be early signs of a reaction.","F"),
(CT,"Contrast improves visualization of which walls most in standard echo?","The anterior and lateral walls, which are often poorly seen",["The septum only","The inferior wall only","The aortic valve"],"Contrast especially helps patients with obesity or lung disease.","F"),
(CT,"High-MI imaging after giving contrast mainly causes:","Rapid bubble destruction and loss of contrast effect",["Longer contrast effect","Better LV opacification","No change"],"Contrast presets use low MI for most imaging.","F"),
(CT,"Agitated saline is not suitable for LV opacification because:","Its bubbles are too large and do not pass through the lung capillaries",["It is too expensive","It is radioactive","It is too small"],"Saline contrast normally stays on the right side.","F"),
]
